// lights_sys: clock domain sys @ 1000000 Hz, generated by Weft from the DAG (51 nodes)
module lights_sys (
  input  wire clk,
  input  wire rst,
  input  wire [0:0] presses_valid,
  input  wire [2:0] presses_data,
  input  wire [0:0] pin_sw_0,
  input  wire [3:0] pin_btn_0_btn_1_btn_2_btn_3,
  input  wire [3:0] buttons_held,
  output wire [7:0] o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7,
  output wire [0:0] x_3,
  output wire [3:0] x_54
);
  wire [0:0] presses_out_ready;  // probe
  wire [0:0] presses_ready;  // probe
  wire [0:0] presses_out_valid;  // probe
  wire [2:0] presses_out_data;  // probe
  reg [0:0] lights_invert_sync1 = 1'h0;
  reg [0:0] lights_invert_sync2 = 1'h0;
  wire [0:0] lights_invert;  // probe
  reg [7:0] lights_leds = 8'h0;
  wire [0:0] lights_on_presses_ready;  // probe
  wire [0:0] n14;
  wire [0:0] n15;
  wire [1:0] n21;
  wire [0:0] n22 = 1'h1;
  wire [3:0] n23;
  wire [7:0] n24;
  wire [0:0] n25 = 1'h0;
  wire [7:0] n26;
  reg [0:0] lights_invert_prev = 1'h0;
  wire [0:0] n28;
  wire [0:0] n29;
  wire [7:0] n30;
  wire [7:0] n31;
  wire [7:0] n32;
  reg [0:0] presses_main_valid = 1'h0;
  reg [2:0] presses_main = 3'h0;
  reg [0:0] presses_skid_valid = 1'h0;
  reg [2:0] presses_skid = 3'h0;
  wire [0:0] n37;
  wire [0:0] n38;
  wire [0:0] n39;
  wire [0:0] n40;
  wire [0:0] n41;
  wire [0:0] n42;
  wire [0:0] n43;
  wire [0:0] n44;
  wire [0:0] n45;
  wire [0:0] n46;
  wire [2:0] n47;
  wire [2:0] n48;
  wire [0:0] n49 = 1'h0;
  wire [0:0] n50;
  wire [0:0] n51;
  wire [0:0] n52;
  wire [2:0] n53;
  assign presses_out_ready = lights_on_presses_ready;
  assign presses_ready = n37;
  assign presses_out_valid = presses_main_valid;
  assign presses_out_data = presses_main;
  assign lights_invert = lights_invert_sync2;
  assign lights_on_presses_ready = n22;
  assign n14 = (|presses_out_valid) && (|lights_on_presses_ready);
  assign n15 = presses_out_data[0:0];  // p.long (line 21)
  assign n21 = presses_out_data[2:1];  // p.id (line 21)
  assign n23 = {{3{1'b0}}, n22} << n21;  // 1 << p.id (line 21)
  assign n24 = lights_leds ^ {{4{1'b0}}, n23};  // $.leds ^ (1 << p.id) (line 21)
  assign n26 = (|n15) ? {{7{1'b0}}, n25} : n24;  // p.long ? 0 : $.leds ^ (1 << p.id) (line 21)
  assign n28 = !(|lights_invert_prev);  // $.leds = p.long ? 0 : $.leds ^ (1 << p.id) (line 21)
  assign n29 = (|lights_invert) && (|n28);  // $.leds = p.long ? 0 : $.leds ^ (1 << p.id) (line 21)
  assign n30 = ~lights_leds;  // ~$.leds (line 23)
  assign n31 = (|n14) ? n26 : lights_leds;  // $.leds = p.long ? 0 : $.leds ^ (1 << p.id) (line 21)
  assign n32 = (|n29) ? n30 : n31;  // $.leds = ~$.leds (line 23)
  assign n37 = !(|presses_skid_valid);
  assign n38 = (|presses_valid) && (|n37);
  assign n39 = (|presses_main_valid) && (|presses_out_ready);
  assign n40 = !(|presses_main_valid);
  assign n41 = (|n39) || (|n40);
  assign n42 = (|presses_skid_valid) || (|n38);
  assign n43 = (|n41) ? n42 : presses_main_valid;
  assign n44 = (|n37) && (|n38);
  assign n45 = (|n41) && (|n44);
  assign n46 = (|n41) && (|presses_skid_valid);
  assign n47 = (|n46) ? presses_skid : presses_main;
  assign n48 = (|n45) ? presses_data : n47;
  assign n50 = (|n41) ? n49 : n42;
  assign n51 = !(|n41);
  assign n52 = (|n51) && (|n38);
  assign n53 = (|n52) ? presses_data : presses_skid;
  assign o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7 = lights_leds;
  assign x_3 = presses_ready;
  assign x_54 = pin_btn_0_btn_1_btn_2_btn_3;
  always @(posedge clk) begin
    lights_invert_sync1 <= rst ? 1'h0 : pin_sw_0;
    lights_invert_sync2 <= rst ? 1'h0 : lights_invert_sync1;
    lights_leds <= rst ? 8'h0 : n32;
    lights_invert_prev <= rst ? 1'h0 : lights_invert;
    presses_main_valid <= rst ? 1'h0 : n43;
    presses_main <= rst ? 3'h0 : n48;
    presses_skid_valid <= rst ? 1'h0 : n50;
    presses_skid <= rst ? 3'h0 : n53;
  end
endmodule

// Native cells used by this design. In the Lab their behaviour is JavaScript. A cell with a hand-written core
// (hdl/cells, added by weft build) gets an adapter from the design's stream signals to the core's ports; any
// other cell is a black box with the interface the design uses.

// debounce cell → weft_core_debounce
module weft_debounce #(parameter LONG_CYC = 0, parameter SETTLE_CYC = 0) (
  input  wire clk,
  input  wire rst,
  output wire [3:0] held,
  output wire [2:0] presses_data,
  input  wire [0:0] presses_ready,
  output wire [0:0] presses_valid,
  input  wire [3:0] raw
);
  weft_core_debounce #(.N(4), .ID_W(2), .LONG_CYC(LONG_CYC), .SETTLE_CYC(SETTLE_CYC)) core (
    .clk(clk),
    .rst(rst),
    .raw(raw),
    .held(held),
    .ev_valid(presses_valid),
    .ev_id(presses_data[2:1]),
    .ev_long(presses_data[0]),
    .ev_ready(presses_ready)
  );
endmodule

// lights: top level generated by Weft — 1 clock domain, 1 native cell
// Clocks are top-level inputs (PLL primitives are not emitted); rst is synchronous and active high.
module lights (
  input  wire [0:0] clk_sys,
  input  wire [0:0] rst,
  input  wire [0:0] sw,
  input  wire [3:0] btn,
  output wire [7:0] led
);
  wire [0:0] sys__presses_valid;
  wire [2:0] sys__presses_data;
  wire [0:0] sys__pin_sw_0;
  wire [3:0] sys__pin_btn_0_btn_1_btn_2_btn_3;
  wire [3:0] sys__buttons_held;
  wire [7:0] sys__o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7;
  wire [0:0] sys__x_3;
  wire [3:0] sys__x_54;
  assign sys__pin_sw_0[0] = sw[0];
  assign sys__pin_btn_0_btn_1_btn_2_btn_3[0] = btn[0];
  assign sys__pin_btn_0_btn_1_btn_2_btn_3[1] = btn[1];
  assign sys__pin_btn_0_btn_1_btn_2_btn_3[2] = btn[2];
  assign sys__pin_btn_0_btn_1_btn_2_btn_3[3] = btn[3];
  assign led[0] = sys__o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7[0];
  assign led[1] = sys__o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7[1];
  assign led[2] = sys__o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7[2];
  assign led[3] = sys__o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7[3];
  assign led[4] = sys__o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7[4];
  assign led[5] = sys__o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7[5];
  assign led[6] = sys__o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7[6];
  assign led[7] = sys__o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7[7];
  lights_sys u_sys (
    .clk(clk_sys),
    .rst(rst),
    .presses_valid(sys__presses_valid),
    .presses_data(sys__presses_data),
    .pin_sw_0(sys__pin_sw_0),
    .pin_btn_0_btn_1_btn_2_btn_3(sys__pin_btn_0_btn_1_btn_2_btn_3),
    .buttons_held(sys__buttons_held),
    .o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7(sys__o_pin_led_0_led_1_led_2_led_3_led_4_led_5_led_6_led_7),
    .x_3(sys__x_3),
    .x_54(sys__x_54)
  );
  weft_debounce #(.LONG_CYC(500000), .SETTLE_CYC(10000)) u_buttons (
    .clk(clk_sys),
    .rst(rst),
    .held(sys__buttons_held),
    .presses_data(sys__presses_data),
    .presses_ready(sys__x_3),
    .presses_valid(sys__presses_valid),
    .raw(sys__x_54)
  );  // native cell buttons (debounce): adapter to weft_core_debounce (hdl/cells)
endmodule
